#!/bin/bash
set -e
echo "============================================================="
echo "🚀 INAANZA KUSASISHA KODI YOTE KWENYE VPS (LATEST UPDATE)..."
echo "============================================================="
cd /var/www/tz-wifi-billing || cd /root/tz-wifi-billing || exit 1

echo "📦 Inaandaa mafaili mapya ya mfumo (src, server, n.k.)..."
cat << 'EOF' | base64 -d > update_pkg.tar.gz

EOF

echo "📂 Inafungua na kubadilisha mafaili..."
tar -xzf update_pkg.tar.gz
rm -f update_pkg.tar.gz

echo "🔨 Inajenga upya application (Build)..."
npm run build

echo "🔄 Inawasha upya seva (PM2)..."
pm2 restart all --update-env || pm2 restart tz-wifi || pm2 start dist/server.js --name tz-wifi || true

echo ""
echo "============================================================="
echo "✅ SASISHO LIMEKAMILIKA KIKAMILIFU! MFUMO UKO LIVE NA TAYARI!"
echo "============================================================="
